// Calculate the average actualNetWeight dynamically for the last 'numRecords' records
let totalWeight = 0;
let count = 0;
//var block = flow.get('block');

// Calculate the average weight for the last 'block' packages

for (let i = 0  ; i < packstemp.length; i++) {
    let el = packstemp[i];
    if (el.actualNetWeight !== null) {
        totalWeight += el.actualNetWeight;
        count++;
    }
}


// Calculate the average weight
let averageWeight = count > 0 ? parseFloat((totalWeight / count).toFixed(2)) : 0;

// Ensure the averageWeight array has the same number of elements as actualNetWeight
